const wordmark = '/brand/visualcorp-wordmark.png';
const symbol = '/brand/visualcorp-symbol.png';

function Brand({ dark = false }) {
  return <Link className={`brand ${dark ? 'brand-dark' : ''}`} to="/" aria-label="Visual Corp, página pública"><img src={wordmark} alt="Visual Corp — Agencia Creativa" /></Link>;
}

const adminLinks = [
  { to: '/admin', label: 'Resumen', icon: LayoutDashboard, end: true },
  { to: '/admin/sitio', label: 'Página pública', icon: Globe2 },
  { to: '/admin/solicitudes', label: 'Solicitudes CRM', icon: Users },
  { to: '/admin/marketing', label: 'Marketing', icon: Megaphone },
  { to: '/admin/respaldo', label: 'Respaldo y migración', icon: Database },
];
const operationsLinks = [
  { to: '/operaciones', label: 'Resumen', icon: LayoutDashboard, end: true },
  { to: '/operaciones/pos', label: 'Punto de venta', icon: ShoppingCart },
  { to: '/operaciones/flujos', label: 'Caja y producción', icon: ClipboardList },
  { to: '/operaciones/cotizador', label: 'Cotizador', icon: FileText },
  { to: '/operaciones/inventario', label: 'Inventario', icon: Boxes },
  { to: '/operaciones/crm', label: 'CRM', icon: Users },
  { to: '/operaciones/clientes', label: 'Clientes', icon: Users },
  { to: '/operaciones/marketing', label: 'Marketing', icon: CalendarDays },
  { to: '/operaciones/equipo', label: 'Equipo y permisos', icon: Users, roles: ['admin','manager'] },
  { to: '/operaciones/catalogo', label: 'Catálogo y tarifas', icon: ShoppingBag, roles: ['admin','manager'] },
];

function AppFrame({ area, children }) {
  const { data } = useWorkspace();
  const { user, roles, signOut } = useAuth();
  const nav = (area === 'admin' ? adminLinks : operationsLinks).filter((link) => !link.roles || roles.includes('owner') || link.roles.some((role) => roles.includes(role)));
  const areaTitle = area === 'admin' ? 'Administración web' : 'Operaciones';
  return <div className="work-app"><aside className="sidebar"><div className="sidebar-brand"><Brand/><button title="Ayuda"><CircleHelp size={18}/></button></div><div className="workspace-pill"><span className="status-dot"/> SESIÓN SEGURA <span>· {roles.join(', ')}</span></div><div className="sidebar-group"><small className="sidebar-caption">{areaTitle.toUpperCase()}</small>{nav.map(({to,label,icon:Icon,end})=><NavLink key={to} end={end} to={to} className={({isActive})=>`sidebar-link ${isActive?'active':''}`}><Icon size={18}/><span>{label}</span>{label==='Solicitudes CRM'&&data.leads.length>0&&<b className="sidebar-count">{data.leads.length}</b>}</NavLink>)}</div><div className="sidebar-bottom">{roles.includes('owner')&&<Link to={area==='admin'?'/operaciones':'/admin'} className="switch-app"><span className="switch-icon"><ArrowUpRight size={16}/></span><span><b>{area==='admin'?'Abrir Operaciones':'Abrir Admin web'}</b><small>Cambiar de espacio</small></span><ChevronRight size={15}/></Link>}<div className="sidebar-profile"><div className="profile-avatar">VC</div><span><b>{user?.email || 'Visual Corp'}</b><small>{roles.join(' · ')}</small></span><button className="icon-button" aria-label="Cerrar sesión" onClick={signOut}><LogOut size={16}/></button></div></div></aside><div className="main-shell"><header className="topbar"><div className="breadcrumbs"><span>{areaTitle}</span><ChevronRight size={14}/><b>{data.settings.name}</b></div><div className="topbar-right"><span className="local-badge"><span className="status-dot"/> Supabase conectado</span><button className="top-avatar" aria-label="Perfil" onClick={signOut}>VC</button></div></header><main className="main-content">{children}<footer className="local-footer">Acceso basado en el perfil autenticado; los datos se protegen con permisos en Supabase.</footer></main></div></div>;
}

function ProtectedPage({ area, children }) {
  const auth = useAuth();
  const [email, setEmail] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [oauthLoading, setOauthLoading] = useState(false);
  const allowed = area === 'website' ? ['website_admin'] : area === 'catalog' || area === 'team' ? ['admin','manager'] : ['admin','manager','advisor','warehouse','production','marketing'];
  if (auth.loading) return <main className="access-screen"><p>Verificando acceso seguro…</p></main>;
  if (!auth.user) return <main className="access-screen"><form className="access-card" onSubmit={async (event)=>{event.preventDefault();setError('');setMessage('');try{await auth.sendSignInLink(email.trim());setMessage('Te enviamos un enlace de acceso al correo. Ábrelo en este mismo navegador para continuar.');}catch(err){setError(err.message||'No pudimos iniciar sesión.');}}}><img src={wordmark} alt="Visual Corp"/><span className="site-eyebrow"><i/> ACCESO INTERNO</span><h1>{area==='website'?'Administración de la página web':'Administración POS y gestión interna'}</h1><p>Inicia sesión con tu cuenta de Google autorizada o solicita un enlace seguro por correo.</p><button className="site-primary-button" type="button" disabled={oauthLoading} onClick={async()=>{setError('');setMessage('');setOauthLoading(true);try{await auth.signInWithGoogle();}catch(err){setError(err.message||'No pudimos iniciar sesión con Google.');setOauthLoading(false);}}}>{oauthLoading?'Conectando con Google…':'Continuar con Google'} <ArrowUpRight size={16}/></button><div className="divider-label">O USA UN ENLACE POR CORREO</div><label>Correo de Visual Corp<input type="email" required autoComplete="email" value={email} onChange={(event)=>setEmail(event.target.value)}/></label><button className="site-primary-button" type="submit">Enviar enlace de acceso <ArrowUpRight size={16}/></button>{message&&<small role="status">{message}</small>}{error&&<small className="access-error" role="alert">{error}</small>}</form></main>;
  if (!auth.canAccess(allowed)) return <main className="access-screen"><section className="access-card"><img src={wordmark} alt="Visual Corp"/><span className="site-eyebrow"><i/> PERMISOS</span><h1>Tu perfil no tiene acceso a este panel.</h1><p>La página web y las operaciones internas usan permisos separados. Solicita al propietario que asigne el rol correspondiente.</p><button className="site-primary-button" onClick={auth.signOut}>Cerrar sesión <LogOut size={16}/></button></section></main>;
  return children;
}

function PageHeading({ eyebrow, title, description, action }) {
  return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div>{action&&<div className="heading-action">{action}</div>}</div>;
}

function StatCard({ label, value, icon: Icon, note, tone = '' }) {
  return <article className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={19}/></div><div className="stat-meta"><span>{label}</span><b>{value}</b><small>{note}</small></div></article>;
}

function AdminHome() {
  const { data } = useWorkspace();
  const navigate = useNavigate();
  const pendingRates = data.catalog.filter((item)=>!item.confirmed).length;
  return <AppFrame area="admin"><PageHeading eyebrow="CENTRO DE CONTROL" title="Tu empresa, en un solo lugar." description="Administra la experiencia pública y revisa la actividad que llega desde el sitio." action={<Link className="button button-dark" to="/">Ver sitio público <ArrowUpRight size={16}/></Link>}/><div className="stat-grid"><StatCard label="Solicitudes nuevas" value={data.leads.filter((item)=>item.stage==='Nuevo').length} icon={Users} note={`${data.leads.length} en total`} tone="violet"/><StatCard label="Cotizaciones" value={data.quotes.length} icon={FileText} note="Registradas localmente" tone="blue"/><StatCard label="Tarifas pendientes" value={pendingRates} icon={BadgeCheck} note="Validación requerida" tone="amber"/><StatCard label="Campañas" value={data.campaigns.length} icon={Megaphone} note="Borradores de marketing" tone="rose"/></div><div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><span className="eyebrow">VISTA GENERAL</span><h2>Actividad reciente</h2></div><Link to="/admin/solicitudes" className="text-link">Abrir CRM <ArrowUpRight size={14}/></Link></div>{data.leads.length===0?<EmptyState icon={Users} title="Aún no hay solicitudes" text="Cuando alguien escriba desde la página pública, la solicitud aparecerá aquí." action={<Link className="button button-outline" to="/">Abrir el sitio público <ArrowUpRight size={15}/></Link>}/>:<div className="activity-list">{data.leads.slice(0,5).map((lead)=><div className="activity-row" key={lead.id}><span className="activity-avatar">{lead.name?.slice(0,1)||'C'}</span><span><b>{lead.name}</b><small>{lead.service||'Consulta general'} · {formatDate(lead.createdAt)}</small></span><StageBadge stage={lead.stage}/></div>)}</div>}</section><section className="panel quick-panel"><div className="panel-heading"><div><span className="eyebrow">ACCESOS RÁPIDOS</span><h2>¿Qué quieres gestionar?</h2></div><BriefcaseBusiness size={19}/></div><div className="quick-links"><Link to="/admin/sitio"><Image/><span><b>Actualizar el sitio</b><small>Mensajes, servicios y contacto</small></span><ChevronRight/></Link><Link to="/admin/catalogo"><ShoppingBag/><span><b>Revisar el catálogo</b><small>{pendingRates} tarifas aún sin validar</small></span><ChevronRight/></Link><Link to="/admin/marketing"><Megaphone/><span><b>Preparar una campaña</b><small>Planificar sin publicar</small></span><ChevronRight/></Link><Link to="/operaciones"><ChartNoAxesCombined/><span><b>Ir a operaciones</b><small>Ventas, cotizaciones e inventario</small></span><ChevronRight/></Link></div></section></div><div className="notice-box"><span><Settings2 size={17}/></span><div><b>Fase de preparación local</b><p>Las tres áreas ya comparten datos en este equipo. Para dar acceso a otros dispositivos hace falta conectar la base central y configurar acceso por usuario.</p></div><button onClick={()=>navigate('/admin/sitio')}>Revisar <ChevronRight size={15}/></button></div></AppFrame>;
}

function WebsiteAdmin() {
  const { data, setData, flash } = useWorkspace();
  const { organizationId } = useAuth();
  const [draft, setDraft] = useState(data.settings);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  useEffect(() => setDraft(data.settings), [data.settings]);
  const save = async (event) => { event.preventDefault(); setSaving(true); setError(''); try { await saveWebsiteContent(draft, data.services, organizationId); setData((current)=>({...current,settings:draft})); flash('Cambios del sitio guardados en la base compartida.'); } catch (err) { setError(err.message || 'No se guardaron los cambios.'); } finally { setSaving(false); } };
  const toggleService=async(id)=>{const next=data.services.map((service)=>service.id===id?{...service,enabled:!service.enabled}:service);setData((current)=>({...current,services:next}));try{await saveWebsiteContent(draft,next,organizationId);flash('Visibilidad del servicio actualizada.');}catch(err){setError(err.message||'No se guardó el servicio.');}};
  return <AppFrame area="admin"><PageHeading eyebrow="ADMINISTRADOR DEL SITIO" title="Página pública" description="Edita textos, controla qué servicios aparecen y previsualiza el sitio en vivo." action={<Link className="button button-outline" to="/">Abrir vista pública <ArrowUpRight size={16}/></Link>}/><div className="editor-grid"><form className="panel form-panel" onSubmit={save}><div className="panel-heading"><div><span className="eyebrow">CONTENIDO PRINCIPAL</span><h2>Mensajes del sitio</h2></div><button className="button button-dark" type="submit"><Check size={16}/> Guardar cambios</button></div><div className="field-grid"><label>Antetítulo<input value={draft.heroEyebrow} onChange={(e)=>setDraft({...draft,heroEyebrow:e.target.value})}/></label><label>Titular principal<input value={draft.heroTitle} onChange={(e)=>setDraft({...draft,heroTitle:e.target.value})}/></label><label className="span-two">Descripción<textarea rows="3" value={draft.heroText} onChange={(e)=>setDraft({...draft,heroText:e.target.value})}/></label><label>Ubicación<input value={draft.location} onChange={(e)=>setDraft({...draft,location:e.target.value})}/></label><label>Contacto principal<input value={draft.contactPhone} onChange={(e)=>setDraft({...draft,contactPhone:e.target.value})}/></label><label>Instagram<input value={draft.instagram} onChange={(e)=>setDraft({...draft,instagram:e.target.value})}/></label></div></form><section className="panel"><div className="panel-heading"><div><span className="eyebrow">CONTENIDO VISIBLE</span><h2>Familias de servicio</h2></div><span className="muted-count">{data.services.filter((service)=>service.enabled).length} visibles</span></div><p className="panel-intro">Las familias reflejan capacidades generales confirmadas. Los materiales, disponibilidad y tiempos quedan por confirmar por proyecto.</p><div className="service-toggle-list">{data.services.map((service)=><label className="toggle-row" key={service.id}><span><b>{service.name}</b><small>{service.description}</small></span><input type="checkbox" checked={service.enabled} onChange={()=>toggleService(service.id)}/></label>)}</div><div className="brand-note"><img src={symbol} alt=""/><span><b>Logotipo Visual Corp</b><small>Se usa el recurso gráfico de la empresa para esta propuesta.</small></span></div></section></div><div className="preview-strip"><span><Globe2 size={17}/> La página pública se actualiza al guardar</span><Link to="/">Ver el resultado <ArrowUpRight size={15}/></Link></div></AppFrame>;
}

function StageBadge({ stage }) {
  const cls = String(stage||'Nuevo').toLowerCase().replaceAll(' ','-');
  return <span className={`stage-badge stage-${cls}`}>{stage||'Nuevo'}</span>;
}

function EmptyState({ icon: Icon, title, text, action }) {
  return <div className="empty-state"><span><Icon size={22}/></span><b>{title}</b><p>{text}</p>{action}</div>;
}

function LeadsTable({ collection='leads', remoteItems, onStatusChange }) {
  const { data, update }=useWorkspace();
  const items=remoteItems ?? data[collection];
  return items.length===0?<EmptyState icon={Users} title="Sin registros todavía" text="Las solicitudes creadas desde la web aparecerán aquí."/>:<div className="table-wrap"><table><thead><tr><th>Contacto</th><th>Interés</th><th>Origen</th><th>Recibido</th><th>Etapa</th></tr></thead><tbody>{items.map((item)=><tr key={item.id}><td><b>{item.name}</b><small>{item.company||item.phone}</small></td><td>{item.service||item.details||'Consulta general'}</td><td>{item.source||'Sitio web'}</td><td>{formatDate(item.createdAt)}</td><td><select className="stage-select" value={item.stage} onChange={(e)=>onStatusChange?onStatusChange(item,e.target.value):update(collection,item.id,{stage:e.target.value})}><option>Nuevo</option><option>Contactado</option><option>Cotizando</option><option>Ganado</option><option>Perdido</option><option>Cerrado</option></select></td></tr>)}</tbody></table></div>;
}

function LeadsPage({ area='admin' }) {
  const { data }=useWorkspace();
  const { user }=useAuth();
  const [remoteLeads,setRemoteLeads]=useState(null);
  useEffect(()=>{if(!supabase||!user)return;let active=true;supabase.from('public_requests').select('*').order('created_at',{ascending:false}).limit(300).then(({data:rows,error})=>{if(!active)return;if(error){window.console.error(error);return;}const stages={new:'Nuevo',contacted:'Contactado',quoted:'Cotizando',won:'Ganado',lost:'Perdido',closed:'Cerrado'};setRemoteLeads((rows||[]).map(row=>({id:row.id,name:row.name,company:row.company,phone:row.phone,service:row.service,details:row.message,source:row.request_type==='quote'?'Cotizador público':'Sitio web',createdAt:row.created_at,stage:stages[row.status]||'Nuevo',remoteStatus:row.status})));});return()=>{active=false;};},[user]);
  const leads=remoteLeads??data.leads;
  const updateRemote=async(item,next)=>{const map={'Nuevo':'new','Contactado':'contacted','Cotizando':'quoted','Ganado':'won','Perdido':'lost','Cerrado':'closed'};const {error}=await supabase.from('public_requests').update({status:map[next],updated_at:new Date().toISOString()}).eq('id',item.id);if(error){window.alert(`No se guardó la etapa: ${error.message}`);return;}setRemoteLeads(current=>current.map(row=>row.id===item.id?{...row,stage:next}:row));};
  return <AppFrame area={area}><PageHeading eyebrow="GESTIÓN DE CLIENTES" title="Solicitudes y CRM" description="Las solicitudes del formulario público quedan disponibles para seguimiento del equipo." action={<span className="local-badge"><span className="status-dot"/> {remoteLeads?'Base compartida':'Cargando solicitudes'}</span>}/><div className="stat-grid compact-stats"><StatCard label="Nuevos" value={leads.filter((item)=>item.stage==='Nuevo').length} icon={Users} note="Por revisar" tone="violet"/><StatCard label="Contactados" value={leads.filter((item)=>item.stage==='Contactado').length} icon={Check} note="En conversación" tone="blue"/><StatCard label="Cotizando" value={leads.filter((item)=>item.stage==='Cotizando').length} icon={FileText} note="Preparando propuesta" tone="amber"/><StatCard label="Ganados" value={leads.filter((item)=>item.stage==='Ganado').length} icon={BadgeCheck} note="Actualización manual" tone="rose"/></div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">EMBUDO COMERCIAL</span><h2>Contactos recientes</h2></div><span className="muted-count">{leads.length} registros</span></div><LeadsTable remoteItems={remoteLeads||undefined} onStatusChange={remoteLeads?updateRemote:undefined}/></section><section className="panel"><div className="panel-heading"><div><span className="eyebrow">COTIZACIONES</span><h2>Seguimiento de propuestas</h2></div><Link className="text-link" to="/operaciones/cotizador">Abrir cotizador <ArrowUpRight size={14}/></Link></div><QuoteTable/></section></AppFrame>;
}

function QuoteTable({ editable=true }) {
  const { data, update }=useWorkspace();
  if (!data.quotes.length) return <EmptyState icon={FileText} title="Sin cotizaciones" text="El equipo puede crear una propuesta desde Operaciones → Cotizador."/>;
  return <div className="table-wrap"><table><thead><tr><th>Referencia</th><th>Cliente</th><th>Concepto</th><th>Total</th><th>Estado</th></tr></thead><tbody>{data.quotes.map((quote)=><tr key={quote.id}><td><b>{quote.code}</b><small>{formatDate(quote.createdAt)}</small></td><td>{quote.customer||'Sin cliente'}</td><td>{quote.itemName} · {quote.quantity} {quote.unit}</td><td>{quote.total===null?'Por confirmar':formatMoney(quote.total)}</td><td>{editable?<select className="stage-select" value={quote.stage} onChange={(e)=>update('quotes',quote.id,{stage:e.target.value})}><option>Borrador</option><option>Enviada</option><option>Aprobada</option><option>Rechazada</option><option>Convertida a venta</option></select>:<StageBadge stage={quote.stage}/>}</td></tr>)}</tbody></table></div>;
}

function CatalogPriceControl({ item, onSave }) {
  const [value, setValue] = useState(item.price ? String(item.price) : '');
  const dirty = Number(value || 0) !== Number(item.price || 0);
  useEffect(() => setValue(item.price ? String(item.price) : ''), [item.price]);
  return <div className="rate-edit"><div className="rate-input"><span>$</span><input aria-label={`Tarifa de ${item.name}`} type="number" min="0" step="0.01" value={value} onChange={(event)=>setValue(event.target.value)} placeholder="Sin tarifa"/></div><button className="rate-save" type="button" disabled={!dirty || Number(value)<0} onClick={()=>onSave(Number(value)||0)} title="Guardar tarifa editada"><Check size={14}/></button>{dirty&&<small>Guarda antes de validar</small>}</div>;
}

function CatalogPage() {
  const { data, update }=useWorkspace();
  const { organizationId } = useAuth();
  const [search,setSearch]=useState('');
  const savePrice=async(item,price)=>{const {error}=await supabase.from('catalog_products').update({price,updated_at:new Date().toISOString()}).eq('id',item.id).eq('organization_id',organizationId);if(error){window.alert(`No se guardó la tarifa: ${error.message}`);return;}update('catalog',item.id,{price,confirmed:true});};
  const filtered=useMemo(()=>data.catalog.filter((item)=>`${item.name} ${item.family}`.toLowerCase().includes(search.toLowerCase())),[data.catalog,search]);
  return <AppFrame area="operations"><PageHeading eyebrow="CATÁLOGO DE VISUAL CORP" title="Productos y tarifas" description="Catálogo de cotizaciones cargado desde Supabase. Los cambios de tarifa autorizados se guardan en la base compartida." action={<span className="rate-pending"><BadgeCheck size={15}/> {data.catalog.length} productos</span>}/><div className="catalog-toolbar panel"><label className="search-box"><Search size={16}/><input value={search} onChange={(e)=>setSearch(e.target.value)} placeholder="Buscar producto o familia"/></label><span>{filtered.length} productos · precios de origen</span></div><section className="panel table-panel"><div className="table-wrap"><table><thead><tr><th>Producto</th><th>Familia</th><th>Normal · USD</th><th>Instalación</th><th>Corporativo</th></tr></thead><tbody>{filtered.slice(0,100).map((item)=><tr key={item.id}><td><div className="catalog-product"><img src={item.image} alt="" loading="lazy"/><span><b>{item.name}</b><small>{item.unit}{item.description?` · ${item.description}`:''}</small></span></div></td><td>{item.family}</td><td><CatalogPriceControl item={item} onSave={(price)=>savePrice(item,price)}/></td><td>{item.installPrice==null?'No disponible':formatMoney(item.installPrice)}</td><td>{item.corporatePrice==null?'No disponible':formatMoney(item.corporatePrice)}</td></tr>)}</tbody></table>{filtered.length>100&&<div className="table-more">Mostrando 100 de {filtered.length}. Filtra por nombre o familia para encontrar otros.</div>}</div></section><div className="notice-box"><span><CircleHelp size={17}/></span><div><b>Catálogo compartido de Visual Corp</b><p>Los precios e imágenes provienen del catálogo de cotizaciones de estebanico.com. Cuando una modalidad no tiene precio registrado, se muestra como no disponible. Las tarifas se guardan con permisos de administración y alimentan el cotizador público.</p></div></div></AppFrame>;
}

function CampaignPage({ area='admin' }) {
  const { data, add, update, remove }=useWorkspace();
  const [form,setForm]=useState({title:'',channel:'Instagram',date:'',goal:''});
  const [showForm,setShowForm]=useState(false);
  const save=(event)=>{event.preventDefault();if(!form.title.trim())return;add('campaigns',{...form,status:'Borrador'});setForm({title:'',channel:'Instagram',date:'',goal:''});setShowForm(false);};
  return <AppFrame area={area}><PageHeading eyebrow="MARKETING" title="Calendario de campañas" description="Organiza ideas, fechas y canales. Esta fase no publica contenido en redes." action={<button className="button button-dark" onClick={()=>setShowForm((value)=>!value)}><Plus size={16}/> Nueva campaña</button>}/>{showForm&&<form className="panel campaign-form" onSubmit={save}><div className="panel-heading"><h2>Nuevo borrador</h2><button type="button" className="icon-button" onClick={()=>setShowForm(false)}><X size={17}/></button></div><div className="field-grid"><label>Título<input required value={form.title} onChange={(e)=>setForm({...form,title:e.target.value})} placeholder="Nombre de la campaña"/></label><label>Canal<select value={form.channel} onChange={(e)=>setForm({...form,channel:e.target.value})}><option>Instagram</option><option>Facebook</option><option>TikTok</option><option>WhatsApp</option><option>Multicanal</option><option>Interno</option></select></label><label>Fecha tentativa<input type="date" value={form.date} onChange={(e)=>setForm({...form,date:e.target.value})}/></label><label>Objetivo<input value={form.goal} onChange={(e)=>setForm({...form,goal:e.target.value})} placeholder="Qué queremos comunicar"/></label></div><button className="button button-dark" type="submit">Guardar borrador</button></form>}<div className="campaign-list">{data.campaigns.length===0?<section className="panel"><EmptyState icon={Megaphone} title="Aún no hay campañas" text="Crea un borrador para organizar contenido y asignar su fecha tentativa." action={<button className="button button-outline" onClick={()=>setShowForm(true)}>Crear campaña <Plus size={15}/></button>}/></section>:data.campaigns.map((campaign)=><article className="panel campaign-card" key={campaign.id}><div className="campaign-avatar"><Megaphone size={20}/></div><div className="campaign-main"><div className="campaign-title"><h2>{campaign.title}</h2><StageBadge stage={campaign.status}/></div><p>{campaign.goal||'Objetivo por definir'}</p><div className="campaign-meta"><span>{campaign.channel}</span><span><CalendarDays size={14}/>{formatDate(campaign.date)}</span></div></div><div className="campaign-actions"><select className="stage-select" value={campaign.status} onChange={(e)=>update('campaigns',campaign.id,{status:e.target.value})}><option>Borrador</option><option>En preparación</option><option>En revisión</option><option>Aprobada</option><option>Publicada</option></select><button className="icon-button danger" onClick={()=>remove('campaigns',campaign.id)} title="Eliminar borrador"><X size={16}/></button></div></article>)}</div><div className="notice-box"><span><CircleHelp size={17}/></span><div><b>La programación no publica automáticamente</b><p>Marcar una campaña como aprobada o publicada es un registro manual y no envía contenido a las redes.</p></div></div></AppFrame>;
}

function OperationsHome() {
  const { data }=useWorkspace();
  const today=new Date().toISOString().slice(0,10);
  const salesToday=data.sales.filter((sale)=>sale.date?.slice(0,10)===today);
  return <AppFrame area="operations"><PageHeading eyebrow="OPERACIONES · PANEL PRINCIPAL" title="Buenos días, equipo." description="Actividad comercial y de trabajo registrada en este equipo." action={<Link to="/operaciones/pos" className="button button-dark">Abrir POS <ArrowUpRight size={16}/></Link>}/><div className="stat-grid"><StatCard label="Ventas del día" value={formatMoney(salesToday.reduce((sum,sale)=>sum+sale.total,0))} icon={Wallet} note={`${salesToday.length} movimientos locales`} tone="blue"/><StatCard label="Solicitudes abiertas" value={data.leads.filter((item)=>!['Ganado','Perdido'].includes(item.stage)).length} icon={Users} note="CRM compartido con la web" tone="violet"/><StatCard label="Cotizaciones" value={data.quotes.length} icon={FileText} note="Incluye tarifas por confirmar" tone="amber"/><StatCard label="Artículos inventariados" value={data.inventory.length} icon={Boxes} note={`${data.inventory.filter((item)=>item.quantity<=item.minimum).length} en nivel mínimo`} tone="rose"/></div><div className="operations-launcher">{operationsLinks.slice(1).map(({to,label,icon:Icon},index)=><Link to={to} key={to} className="operation-card"><span className={`operation-icon operation-${index}`}><Icon size={20}/></span><span><b>{label}</b><small>{['Registrar movimientos de venta','Crear propuestas y compartirlas internamente','Controlar materiales y alertas de stock','Dar seguimiento a clientes y oportunidades','Administrar contactos y datos de clientes','Preparar calendario y estados de campaña'][index]}</small></span><ChevronRight size={17}/></Link>)}</div><section className="panel"><div className="panel-heading"><div><span className="eyebrow">SEGUIMIENTO</span><h2>Solicitudes recientes</h2></div><Link className="text-link" to="/operaciones/crm">Ver CRM <ArrowUpRight size={14}/></Link></div><LeadsTable/></section></AppFrame>;
}

function PosPage() {
  const { data, add, update, flash, refreshRemote }=useWorkspace();
  const { organizationId, user }=useAuth();
  const [form,setForm]=useState({total:'',amountPaid:'',method:'Efectivo',customer:'',customerId:'',customerPhone:'',description:'',productId:'',branchCode:'VIS',quantity:'1',quoteId:''});
  const [catalogLinks,setCatalogLinks]=useState([]);
  const [centralQuotes,setCentralQuotes]=useState([]);
  const [paymentTarget,setPaymentTarget]=useState(null);
  const [paymentForm,setPaymentForm]=useState({amount:'',method:'Efectivo'});
  const pendingSaleKey=useRef(typeof window!=='undefined'?sessionStorage.getItem('visualcorp-pos-pending-sale-key')||'':'');
  useEffect(()=>{if(!supabase||!organizationId)return;let active=true;Promise.all([supabase.from('catalog_inventory_links').select('catalog_product_id,inventory_variant_id,branch_id,location_code,active').eq('organization_id',organizationId).eq('active',true),supabase.from('central_quotes').select('*').eq('organization_id',organizationId).order('created_at',{ascending:false}).limit(100)]).then(([links,quotes])=>{if(!active)return;if(links.error)flash(`No se pudieron cargar los vínculos de stock: ${links.error.message}`);else setCatalogLinks(links.data||[]);if(quotes.error)flash(`No se pudieron cargar cotizaciones centrales: ${quotes.error.message}`);else setCentralQuotes(quotes.data||[]);});return()=>{active=false;};},[organizationId]);
  const today=localDateKey();
  const salesToday=data.sales.filter((sale)=>localDateKey(sale.date)===today);
  const selectedProduct=data.catalog.find((product)=>product.id===form.productId);
  const branchName=form.branchCode==='GIGA'?'Gigaprint':'Visual Corp';
  const productLink=catalogLinks.find((link)=>link.catalog_product_id===form.productId&&data.inventory.some((row)=>row.variantId===link.inventory_variant_id&&row.branchId===link.branch_id&&row.branch===branchName));
  const stockItem=productLink?data.inventory.find((row)=>row.variantId===productLink.inventory_variant_id&&row.branchId===productLink.branch_id):null;
  const save=async(event)=>{
    event.preventDefault();
    const total=Number(form.total);const requestedQty=Math.max(1,Math.floor(Number(form.quantity)||1));
    if(!Number.isInteger(Number(form.quantity))||Number(form.quantity)<1){flash('Por ahora, las cantidades del POS deben ser unidades enteras.');return;}
    if(!total||total<=0||!user||!organizationId)return;
    const short=Boolean(stockItem&&(stockItem.sourceStatus||Number(stockItem.quantity)<requestedQty));
    if(short&&!window.confirm(`${stockItem.sourceStatus?'El stock todavía no tiene conteo confirmado.':`Hay ${stockItem.quantity} ${stockItem.unit} de ${stockItem.name} y solicitas ${requestedQty}.`} ¿Confirmar la orden y dejar el faltante como compra urgente?`))return;
    try{
      const quote=centralQuotes.find(q=>q.id===form.quoteId);
      if(form.quoteId&&(!quote||quote.status!=='accepted'||!quote.price_confirmed||Math.round(Number(quote.selected_total)*100)!==Math.round(total*100))){flash('La cotización debe seguir aceptada y el total debe coincidir exactamente antes de confirmar.');return;}
      let quoteLinkError='';
      if(form.method==='Efectivo'&&Number(form.amountPaid===''?total:form.amountPaid)>0){const {data:branch}=await supabase.from('branches').select('id').eq('organization_id',organizationId).eq('code',form.branchCode).maybeSingle();const {data:shift,error:shiftError}=await supabase.from('cash_sessions').select('id').eq('organization_id',organizationId).eq('branch_id',branch?.id||'').eq('opened_by',user.id).eq('status','open').maybeSingle();if(shiftError)throw shiftError;if(!shift){flash('Abre primero tu turno de caja en Caja y producción antes de cobrar en efectivo.');return;}}
      if(!pendingSaleKey.current){pendingSaleKey.current=globalThis.crypto?.randomUUID?.()||`sale-${Date.now()}-${Math.random().toString(36).slice(2)}`;sessionStorage.setItem('visualcorp-pos-pending-sale-key',pendingSaleKey.current);}
      const methodMap={Efectivo:'cash',Transferencia:'transfer',Tarjeta:'card',Otro:'other'};
      const {data:sale,error}=await supabase.rpc('create_pos_sale_idempotent',{
        p_idempotency_key:pendingSaleKey.current,
        p_branch_code:form.branchCode,
        p_customer_id:form.customerId||null,
        p_customer_data:{full_name:form.customer.trim(),phone:form.customerPhone.trim()},
        p_discount:0,
         p_note:[form.description,quote?`Cotización ${quote.quote_code}`:''].filter(Boolean).join(' · '),
        p_allow_backorder:true,
        p_lines:(()=>{const cents=Math.round(total*100);const base=Math.floor(cents/requestedQty);const remainder=cents-base*requestedQty;return Array.from({length:requestedQty},(_,index)=>({catalog_product_id:form.productId||null,sku:selectedProduct?.id||'',description:form.description||selectedProduct?.name||'Venta POS',quantity:1,unit_price:(base+(index<remainder?1:0))/100}));})(),
        p_payments:Number(form.amountPaid===''?total:form.amountPaid)>0?[{method:methodMap[form.method]||'other',amount:Number(form.amountPaid===''?total:form.amountPaid)}]:[],
      });
      if(error)throw error;
       if(form.quoteId){const {error:quoteError}=await supabase.rpc('link_pos_sale_to_central_quote',{p_sale:sale.sale_id,p_quote:form.quoteId});if(quoteError)quoteLinkError=quoteError.message;else setCentralQuotes(rows=>rows.map(q=>q.id===form.quoteId?{...q,status:'converted'}:q));}
      await refreshRemote();
      setForm({total:'',amountPaid:'',method:'Efectivo',customer:'',customerId:'',customerPhone:'',description:'',productId:'',branchCode:'VIS',quantity:'1',quoteId:''});
      sessionStorage.removeItem('visualcorp-pos-pending-sale-key');pendingSaleKey.current='';
      flash(quoteLinkError?`Venta ${sale.sale_code||''} registrada, pero la cotización no quedó vinculada: ${quoteLinkError}`:sale.backordered_quantity?'Orden confirmada; el faltante quedó como compra urgente.':'Orden confirmada y guardada en Supabase.');
    }catch(error){flash(`No se confirmó la orden; el formulario se conserva para reintentar: ${error.message}`);}
  };
  const registerBalancePayment=async(event,sale)=>{
    event.preventDefault();const amount=Number(paymentForm.amount);if(!amount||amount<=0)return;
    try{const keyName=`visualcorp-pos-payment-${sale.id}`;let key=sessionStorage.getItem(keyName);if(!key){key=globalThis.crypto?.randomUUID?.()||`payment-${Date.now()}-${Math.random().toString(36).slice(2)}`;sessionStorage.setItem(keyName,key);}const methodMap={Efectivo:'cash',Transferencia:'transfer',Tarjeta:'card',Otro:'other'};const {error}=await supabase.rpc('record_sale_payment',{p_idempotency_key:key,p_sale_id:sale.id,p_method:methodMap[paymentForm.method]||'other',p_amount:amount,p_reference:'',p_note:''});if(error)throw error;sessionStorage.removeItem(keyName);await refreshRemote();setPaymentTarget(null);setPaymentForm({amount:'',method:'Efectivo'});flash('Abono guardado y saldo actualizado.');}catch(error){flash(`No se guardó el abono; puedes reintentar sin duplicarlo: ${error.message}`);}
  };
  return <AppFrame area="operations"><PageHeading eyebrow="PUNTO DE VENTA" title="Caja y ventas" description="Registra órdenes compartidas con inventario, clientes y pagos." action={<span className="local-badge"><span className="status-dot"/> Supabase conectado</span>}/><div className="stat-grid compact-stats"><StatCard label="Total registrado hoy" value={formatMoney(salesToday.reduce((sum,sale)=>sum+sale.total,0))} icon={Wallet} note={`${salesToday.length} órdenes confirmadas`} tone="blue"/><StatCard label="Transacciones" value={salesToday.length} icon={ShoppingCart} note="Todas las sucursales" tone="violet"/><StatCard label="Método principal" value={salesToday.length?mostFrequent(salesToday.map((sale)=>sale.method)):'—'} icon={ArrowDownRight} note="Pagos registrados" tone="amber"/></div><div className="pos-grid"><form className="panel form-panel" onSubmit={save}><div className="panel-heading"><div><span className="eyebrow">NUEVA ORDEN</span><h2>Confirmar venta</h2></div><ShoppingCart size={19}/></div><label>Cobrar propuesta aprobada<select value={form.quoteId} onChange={(e)=>{const quote=centralQuotes.find((item)=>item.id===e.target.value);setForm({...form,quoteId:e.target.value,total:quote?.selected_total??'',amountPaid:quote?.selected_total??'',customer:quote?.customer_name||'',description:Array.isArray(quote?.items)?quote.items.map(i=>i.name||i.product_name).join(', '):''});}}><option value="">Venta manual (sin cotización)</option>{centralQuotes.filter((quote)=>quote.status==='accepted'&&quote.price_confirmed&&quote.selected_total!==null).map((quote)=><option key={quote.id} value={quote.id}>{quote.quote_code} · {quote.customer_name||'Cliente'} · {formatMoney(quote.selected_total)}</option>)}</select></label><label>Valor acordado (USD) *<div className="money-input"><span>$</span><input type="number" min="0.01" step="0.01" required value={form.total} onChange={(e)=>setForm({...form,total:e.target.value})} placeholder="0,00"/></div></label><label>Forma de pago<select value={form.method} onChange={(e)=>setForm({...form,method:e.target.value})}><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option><option>Otro</option></select></label><label>Pago recibido ahora (USD)<div className="money-input"><span>$</span><input type="number" min="0" step="0.01" value={form.amountPaid} onChange={(e)=>setForm({...form,amountPaid:e.target.value})} placeholder="Vacío = pago completo"/></div></label><label>Sucursal<select value={form.branchCode} onChange={(e)=>setForm({...form,branchCode:e.target.value})}><option value="VIS">Visual Corp</option><option value="GIGA">Gigaprint</option></select></label><label>Producto del catálogo<select value={form.productId} onChange={(e)=>setForm({...form,productId:e.target.value})}><option value="">Concepto libre / servicio sin stock</option>{data.catalog.map((product)=><option key={product.id} value={product.id}>{product.family} · {product.name}</option>)}</select></label>{selectedProduct&&<div className="notice-box"><span><Boxes size={16}/></span><div><b>{stockItem?`${stockItem.name}${stockItem.variant?` · ${stockItem.variant}`:''}`:'Sin vínculo a inventario'}</b><p>{stockItem?(stockItem.sourceStatus?'Conteo físico pendiente; puedes confirmar la venta como compra urgente.':`Disponible: ${stockItem.quantity} ${stockItem.unit}.`):'Esta venta no modificará el stock hasta asignar una variante física en Inventario.'}</p></div></div>}<label>Elegir cliente<select value={form.customerId} onChange={(e)=>{const customer=data.customers.find((row)=>row.id===e.target.value);setForm({...form,customerId:e.target.value,customer:customer?.name||'',customerPhone:customer?.phone||''});}}><option value="">Nuevo cliente / sin asociar</option>{(data.customers||[]).map((customer)=><option key={customer.id} value={customer.id}>{customer.name}{customer.phone?` · ${customer.phone}`:''}</option>)}</select></label><label>Nombre del cliente<input value={form.customer} onChange={(e)=>setForm({...form,customerId:'',customer:e.target.value})} placeholder="Nombre o razón social"/></label><label>Teléfono<input value={form.customerPhone} onChange={(e)=>setForm({...form,customerId:'',customerPhone:e.target.value})} placeholder="Opcional"/></label><label>Concepto / notas<textarea rows="2" value={form.description} onChange={(e)=>setForm({...form,description:e.target.value})} placeholder={selectedProduct?.name||'Producto o servicio'}/></label><label>Cantidad vendida<input type="number" min="1" step="1" value={form.quantity} onChange={(e)=>setForm({...form,quantity:e.target.value})}/></label><button className="button button-dark form-submit" type="submit">Confirmar orden <Check size={16}/></button></form><section className="panel"><div className="panel-heading"><div><span className="eyebrow">CAJA DEL DÍA</span><h2>Órdenes recientes</h2></div><span className="muted-count">{salesToday.length} registros</span></div>{salesToday.length===0?<EmptyState icon={Wallet} title="Todavía no hay ventas" text="Al confirmar una orden, aparecerá con sus pagos y movimientos."/>:<div className="activity-list">{salesToday.map((sale)=><article className="sale-activity" key={sale.id}><div className="sale-row"><span className="sale-icon"><ShoppingCart size={17}/></span><span><b>{sale.customer||sale.description||'Venta'}</b><small>{sale.method} · {new Date(sale.date).toLocaleTimeString('es-EC',{hour:'2-digit',minute:'2-digit'})} · {sale.code}</small></span><strong>{formatMoney(sale.total)}</strong></div><div className="sale-payment-summary"><span>Abonado: <b>{formatMoney(sale.paid||0)}</b></span><span>Saldo: <b>{formatMoney(sale.balance||0)}</b></span>{sale.urgent&&<span className="inventory-status pending">Compra urgente pendiente</span>}</div>{Number(sale.balance)>0&&<><button className="button button-outline" type="button" onClick={()=>{setPaymentTarget(paymentTarget===sale.id?null:sale.id);setPaymentForm({amount:String(sale.balance),method:'Efectivo'});}}>Registrar abono</button>{paymentTarget===sale.id&&<form className="payment-form" onSubmit={(event)=>registerBalancePayment(event,sale)}><label>Monto recibido<input type="number" min="0.01" max={sale.balance} step="0.01" required value={paymentForm.amount} onChange={(e)=>setPaymentForm({...paymentForm,amount:e.target.value})}/></label><label>Forma de pago<select value={paymentForm.method} onChange={(e)=>setPaymentForm({...paymentForm,method:e.target.value})}><option>Efectivo</option><option>Transferencia</option><option>Tarjeta</option><option>Otro</option></select></label><button className="button button-dark" type="submit">Guardar abono</button></form>}</>}</article>)}</div>}</section></div><div className="notice-box"><span><CircleHelp size={17}/></span><div><b>Control conectado</b><p>La orden se confirma con una clave de reintento; el stock se reserva al confirmar, los abonos se pueden completar después y cualquier faltante de una variante vinculada queda señalado como compra urgente. El POS no emite comprobantes tributarios.</p></div></div></AppFrame>;
}

function mostFrequent(values) { return values.sort((a,b)=>values.filter((item)=>item===b).length-values.filter((item)=>item===a).length)[0]; }

function QuotePage() {
  const { data, flash }=useWorkspace();
  const { organizationId }=useAuth();
  const [term,setTerm]=useState('');
  const [productId,setProductId]=useState('');
  const [qty,setQty]=useState(1);
  const [widthCm,setWidthCm]=useState(100);
  const [heightCm,setHeightCm]=useState(100);
  const [priceTier,setPriceTier]=useState('pvp');
  const [optionPrice,setOptionPrice]=useState('');
  const [customer,setCustomer]=useState('');
  const [phone,setPhone]=useState('');
  const [itemLabel,setItemLabel]=useState('');
  const [centralQuotes,setCentralQuotes]=useState([]);
  const [saving,setSaving]=useState(false);
  const [quoteError,setQuoteError]=useState('');
  useEffect(()=>{if(!supabase||!organizationId)return;let active=true;supabase.from('central_quotes').select('*').eq('organization_id',organizationId).order('created_at',{ascending:false}).limit(100).then(({data:rows,error})=>{if(!active)return;if(error)setQuoteError(error.message);else setCentralQuotes(rows||[]);});return()=>{active=false;};},[organizationId]);
  const matched=useMemo(()=>data.catalog.filter((item)=>`${item.name} ${item.family}`.toLowerCase().includes(term.toLowerCase())).slice(0,80),[data.catalog,term]);
  const selected=data.catalog.find((item)=>item.id===productId);
  const area=selected?.mode==='area'?(Math.max(0,Number(widthCm)||0)*Math.max(0,Number(heightCm)||0))/10000:0;
  const basis=getQuoteBasis(selected,{quantity:qty,area});
  const total=calculateQuotePrice(selected,priceTier,basis);
  const confirmedTotal=selected?.confirmed?total:null;
  const selectedTierLabel=priceTier==='instalacion'?'Con instalación':priceTier==='corporativo'?'Corporativo':'Normal';
  const save=async(event)=>{event.preventDefault();if(!selected||!supabase||!organizationId)return;setSaving(true);setQuoteError('');try{const totals={normal:calculateQuotePrice(selected,'pvp',basis,optionPrice),installation:calculateQuotePrice(selected,'instalacion',basis,optionPrice),corporate:calculateQuotePrice(selected,'corporativo',basis,optionPrice)};const chosen={pvp:'normal',instalacion:'installation',corporativo:'corporate'}[priceTier]||'normal';const {data:result,error}=await supabase.rpc('create_central_quote',{p_customer_id:null,p_customer_name:customer.trim(),p_customer_phone:phone.trim(),p_items:[{product_id:selected.id,name:itemLabel.trim()||selected.name,category:selected.family,quantity:basis,unit:selected.mode==='area'?'m²':selected.unit,total:confirmedTotal,price_tier:priceTier,option:optionPrice||null,width_cm:selected.mode==='area'?Number(widthCm):null,height_cm:selected.mode==='area'?Number(heightCm):null,image:selected.image||null}],p_normal:totals.normal,p_installation:totals.installation,p_corporate:totals.corporate,p_chosen:chosen,p_selected:confirmedTotal,p_confirmed:Boolean(selected.confirmed),p_notes:''});if(error)throw error;const {data:rows,error:readError}=await supabase.from('central_quotes').select('*').eq('organization_id',organizationId).order('created_at',{ascending:false}).limit(100);if(readError)throw readError;setCentralQuotes(rows||[]);setProductId('');setItemLabel('');setCustomer('');setPhone('');setQty(1);setWidthCm(100);setHeightCm(100);setPriceTier('pvp');setOptionPrice('');setTerm('');flash(`Cotización ${result.quote_code} guardada y sincronizada.`);}catch(error){setQuoteError(error.message||'No se pudo sincronizar la cotización.');}finally{setSaving(false);}};
  return <AppFrame area="operations"><PageHeading eyebrow="COTIZADOR" title="Tres tarifas, en tiempo real." description="Compara las tarifas normal, con instalación y corporativa desde el catálogo compartido."/><div className="quote-grid"><form className="panel form-panel" onSubmit={save}><div className="panel-heading"><div><span className="eyebrow">NUEVA PROPUESTA</span><h2>Detalle de cotización</h2></div><FileText size={19}/></div><label>Buscar en el catálogo<div className="search-input"><Search size={16}/><input value={term} onChange={(e)=>setTerm(e.target.value)} placeholder="Producto o familia"/></div></label><label>Selecciona un producto<select required value={productId} onChange={(e)=>{setProductId(e.target.value);setPriceTier('pvp');setOptionPrice('');}}><option value="">Elige del catálogo ({data.catalog.length})</option>{matched.map((item)=><option key={item.id} value={item.id}>{item.family} · {item.name}{!item.confirmed?' · tarifa pendiente':''}</option>)}</select></label>
    {selected?.mode==='area'&&<div className="field-grid"><label>Ancho (cm)<input type="number" min="1" step="any" value={widthCm} onChange={(e)=>setWidthCm(e.target.value)}/></label><label>Alto (cm)<input type="number" min="1" step="any" value={heightCm} onChange={(e)=>setHeightCm(e.target.value)}/></label><div className="quote-area-readout">Área por pieza <b>{area.toFixed(2)} m²</b></div></div>}
    <div className="form-row"><label>{selected?.mode==='area'?'Cantidad de piezas':'Cantidad'}<input min="1" step="1" type="number" value={qty} onChange={(e)=>setQty(e.target.value)}/></label><label>Concepto (opcional)<input value={itemLabel} onChange={(e)=>setItemLabel(e.target.value)} placeholder="Descripción para el cliente"/></label></div>
    {selected&&<><div className="quote-product-preview"><img src={selected.image} alt=""/><div><b>{selected.name}</b><small>{selected.description||selected.family}</small></div></div>{selected.optionPrices?.length>0&&<label>Opción<select value={optionPrice} onChange={(e)=>setOptionPrice(e.target.value)}><option value="">Selecciona una opción</option>{selected.optionPrices.map((option,index)=><option key={`${option.label}-${index}`} value={option.label}>{option.label} · {formatMoney(option.price)}</option>)}</select></label>}<QuotePriceComparison product={selected} basis={basis} selectedTier={priceTier} optionChoice={optionPrice} onSelect={setPriceTier}/></>}
    <div className="divider-label">DATOS DEL CLIENTE · OPCIONAL</div><div className="form-row"><label>Nombre<input value={customer} onChange={(e)=>setCustomer(e.target.value)} placeholder="Cliente o empresa"/></label><label>Teléfono<input value={phone} onChange={(e)=>setPhone(e.target.value)} placeholder="09…"/></label></div><div className="quote-total"><span>Total de la propuesta · {selectedTierLabel}</span><b>{!selected?'Selecciona un producto':!selected.confirmed?'Pendiente de validar':confirmedTotal===null?'Sin tarifa para esta opción':formatMoney(confirmedTotal)}</b></div>{quoteError&&<div className="op-flow-alert error">{quoteError}</div>}<button className="button button-dark form-submit" disabled={!selected||total===null||saving} type="submit">{saving?'Guardando…':'Guardar cotización central'} <Check size={16}/></button></form><section className="panel"><div className="panel-heading"><div><span className="eyebrow">HISTORIAL COMPARTIDO</span><h2>Propuestas recientes</h2></div><span className="muted-count">{centralQuotes.length} en total</span></div><div className="activity-list">{centralQuotes.slice(0,30).map(q=><article className="sale-activity" key={q.id}><div className="sale-row"><span className="sale-icon"><FileText size={17}/></span><span><b>{q.quote_code} · {q.customer_name||'Sin cliente'}</b><small>{Array.isArray(q.items)?q.items.map(i=>i.name).join(', '):''} · {new Date(q.created_at).toLocaleDateString('es-EC')}</small></span><strong>{q.selected_total===null?'Por validar':formatMoney(q.selected_total)}</strong></div><div className="sale-payment-summary"><span>Estado: <b>{q.status}</b></span><span>Tarifa: <b>{q.price_confirmed?'Confirmada':'Por confirmar'}</b></span></div></article>)}{!centralQuotes.length&&<EmptyState icon={FileText} title="Aún no hay cotizaciones" text="Las propuestas guardadas aquí se sincronizan con el equipo."/>}</div></section></div><div className="notice-box"><span><CircleHelp size={17}/></span><div><b>Cotizaciones sincronizadas</b><p>Las nuevas propuestas guardan sus artículos, imágenes, tarifa seleccionada, las tres opciones disponibles y el estado en Supabase para que el POS y el equipo consulten el mismo historial.</p></div></div></AppFrame>;
}

function InventoryPageLegacy() {
  const { data, add, update, remove }=useWorkspace();
  const [form,setForm]=useState({name:'',quantity:'',unit:'unidad',minimum:'0'});
  const [showForm,setShowForm]=useState(false);
  const save=(event)=>{event.preventDefault();if(!form.name.trim())return;add('inventory',{...form,quantity:Number(form.quantity)||0,minimum:Number(form.minimum)||0,unit:form.unit||'unidad'});setForm({name:'',quantity:'',unit:'unidad',minimum:'0'});setShowForm(false);};
  return <AppFrame area="operations"><PageHeading eyebrow="INVENTARIO" title="Materiales y existencias" description="Registra materiales manualmente y define un nivel mínimo de alerta." action={<button className="button button-dark" onClick={()=>setShowForm(!showForm)}><Plus size={16}/> Añadir material</button>}/><div className="stat-grid compact-stats"><StatCard label="Materiales" value={data.inventory.length} icon={Boxes} note="Registros locales" tone="violet"/><StatCard label="Stock bajo" value={data.inventory.filter((item)=>item.quantity<=item.minimum).length} icon={ArrowDownRight} note="En o bajo mínimo" tone="amber"/><StatCard label="Unidades registradas" value={data.inventory.reduce((sum,item)=>sum+Number(item.quantity),0)} icon={Package} note="Suma de cantidades" tone="blue"/></div>{showForm&&<form className="panel campaign-form" onSubmit={save}><div className="panel-heading"><h2>Nuevo material</h2><button type="button" className="icon-button" onClick={()=>setShowForm(false)}><X size={17}/></button></div><div className="field-grid"><label>Nombre<input required value={form.name} onChange={(e)=>setForm({...form,name:e.target.value})} placeholder="Ej. Material"/></label><label>Cantidad inicial<input type="number" min="0" step="any" value={form.quantity} onChange={(e)=>setForm({...form,quantity:e.target.value})}/></label><label>Unidad<input value={form.unit} onChange={(e)=>setForm({...form,unit:e.target.value})} placeholder="unidad, m, pliego…"/></label><label>Nivel mínimo<input type="number" min="0" step="any" value={form.minimum} onChange={(e)=>setForm({...form,minimum:e.target.value})}/></label></div><button className="button button-dark" type="submit">Guardar material <Check size={15}/></button></form>}<section className="panel"><div className="panel-heading"><div><span className="eyebrow">CONTROL DE EXISTENCIAS</span><h2>Inventario</h2></div><span className="muted-count">{data.inventory.length} materiales</span></div>{data.inventory.length===0?<EmptyState icon={Boxes} title="Inventario vacío" text="Añade el primer material; no se importaron existencias de otros sistemas." action={<button className="button button-outline" onClick={()=>setShowForm(true)}>Añadir material <Plus size={15}/></button>}/>:<div className="table-wrap"><table><thead><tr><th>Material</th><th>Existencia</th><th>Mínimo</th><th>Estado</th><th>Acción</th></tr></thead><tbody>{data.inventory.map((item)=><tr key={item.id}><td><b>{item.name}</b><small>Actualizado {formatDate(item.updatedAt||item.createdAt)}</small></td><td><div className="quantity-edit"><button onClick={()=>update('inventory',item.id,{quantity:Math.max(0,Number(item.quantity)-1)})}>−</button><strong>{item.quantity}</strong><span>{item.unit}</span><button onClick={()=>update('inventory',item.id,{quantity:Number(item.quantity)+1})}>+</button></div></td><td>{item.minimum} {item.unit}</td><td><StageBadge stage={Number(item.quantity)<=Number(item.minimum)?'Stock bajo':'Disponible'}/></td><td><button className="icon-button danger" onClick={()=>remove('inventory',item.id)} title="Eliminar material"><X size={16}/></button></td></tr>)}</tbody></table></div>}</section><div className="notice-box"><span><CircleHelp size={17}/></span><div><b>Existencias locales de prueba</b><p>Esta etapa no sincroniza con máquinas, compras, bodegas ni otros dispositivos. No se traspasaron materiales de GigaPrint.</p></div></div></AppFrame>;
}

function InventoryPage() { return <AppFrame area="operations"><PageHeading eyebrow="INVENTARIO" title="Existencias y movimientos" description="Consulta stock por sucursal y área; registra entradas, consumos, mermas y traspasos con responsable."/><InventoryWorkspace/></AppFrame>; }

function AppRouter() {
  const location=useLocation();
  if(location.pathname==='/publico') return <Navigate to="/" replace/>;
  return <Routes>
    <Route element={<PublicSiteLayout/>}>
      <Route path="/" element={<PublicHomePage/>}/>
      <Route path="/servicios" element={<ServicesIndexPage/>}/>
      <Route path="/servicios/:slug" element={<ServiceDetailPage/>}/>
      <Route path="/nosotros" element={<AboutPage/>}/>
      <Route path="/como-trabajamos" element={<ProcessPage/>}/>
      <Route path="/contacto" element={<ContactPage/>}/>
      <Route path="/cotizador" element={<MultiPageQuotePage/>}/>
    </Route>
    <Route path="/admin" element={<ProtectedPage area="website"><AdminHome/></ProtectedPage>}/><Route path="/admin/sitio" element={<ProtectedPage area="website"><WebsiteAdmin/></ProtectedPage>}/><Route path="/admin/solicitudes" element={<ProtectedPage area="website"><LeadsPage/></ProtectedPage>}/><Route path="/operaciones/catalogo" element={<ProtectedPage area="catalog"><CatalogPage/></ProtectedPage>}/><Route path="/admin/catalogo" element={<Navigate to="/operaciones/catalogo" replace/>}/><Route path="/admin/marketing" element={<ProtectedPage area="website"><CampaignPage/></ProtectedPage>}/><Route path="/admin/respaldo" element={<ProtectedPage area="website"><AppFrame area="admin"><PageHeading eyebrow="DATOS" title="Respaldo y migración" description="Consulta el respaldo y la procedencia de datos."/><BackupWorkspace/></AppFrame></ProtectedPage>}/>
    <Route path="/operaciones" element={<ProtectedPage area="operations"><OperationsHome/></ProtectedPage>}/><Route path="/operaciones/pos" element={<ProtectedPage area="operations"><PosPage/></ProtectedPage>}/><Route path="/operaciones/flujos" element={<ProtectedPage area="operations"><AppFrame area="operations"><PageHeading eyebrow="OPERACIONES" title="Flujos conectados" description="Gestiona caja, devoluciones, traslados, producción y cotizaciones desde el mismo registro compartido."/><OperationsLifecycle/></AppFrame></ProtectedPage>}/><Route path="/operaciones/cotizador" element={<ProtectedPage area="operations"><QuotePage/></ProtectedPage>}/><Route path="/operaciones/inventario" element={<ProtectedPage area="operations"><InventoryPage/></ProtectedPage>}/><Route path="/operaciones/clientes" element={<ProtectedPage area="operations"><AppFrame area="operations"><CustomerBook/></AppFrame></ProtectedPage>}/><Route path="/operaciones/crm" element={<ProtectedPage area="operations"><LeadsPage area="operations"/></ProtectedPage>}/><Route path="/operaciones/marketing" element={<ProtectedPage area="operations"><CampaignPage area="operations"/></ProtectedPage>}/><Route path="/operaciones/equipo" element={<ProtectedPage area="team"><AppFrame area="operations"><TeamAccess/></AppFrame></ProtectedPage>}/>
    <Route path="*" element={<Navigate to="/" replace/>}/>
  </Routes>;
}

export default function App() {
  return <BrowserRouter><AuthProvider><WorkspaceProvider><AppRouter/></WorkspaceProvider></AuthProvider></BrowserRouter>;
}
